import React, { useEffect, useMemo, useState } from "react";
import { Routes, Route, Link, useLocation, useNavigate, useParams, useSearchParams, Navigate } from "react-router-dom";
import { onAuthStateChanged } from "firebase/auth";
import { Bell, Search, SlidersHorizontal, ChevronLeft, ChevronRight, Plus, Home, Grid2X2, Heart, UserRound, Phone, MapPin, Clock3, Star, Eye, ShieldCheck, LogOut, Megaphone, Users, Tags, CreditCard, Settings, Trash2, Pencil, CheckCircle2, Upload, ArrowRight, Save, RefreshCw, Sparkles, X, Filter, Camera, UserCircle2, Tag } from "lucide-react";
